import { describe, expect, it } from 'vitest';
import { Add, Mul, Pow, Rational, Sym, add, fn, mul, pi, pow, ratsimp, ratsimpmodprime, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.simplify.ratsimp", () => {
  it("ratsimp(1/x + 1/y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(ratsimp(add(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), pow(y, Rational.of(-1n, 1n, { gcd: 1n })))))).toBe('(x + y)/(x*y)');
  });
  it("ratsimpmodprime(eq, [x*y**5 - x - y], x, y, order='lex')", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(ratsimpmodprime(mul(pow(add(x, mul(Rational.of(-1n, 1n, { gcd: 1n }), y)), Rational.of(-1n, 1n, { gcd: 1n })), add(x, y, pow(y, Rational.of(5n, 1n, { gcd: 1n })))), [add(mul(Rational.of(-1n, 1n, { gcd: 1n }), x), mul(Rational.of(-1n, 1n, { gcd: 1n }), y), mul(x, pow(y, Rational.of(5n, 1n, { gcd: 1n }))))], [x, y], { order: 'lex' }))).toBe('(-x**2 - x*y - x - y)/(-x**2 + x*y)');
  });
});

